SELECT MEDIAN(p.stoptime - p.starttime) AS median_duration FROM prescriptions p JOIN patients pt ON p.subject_id = pt.subject_id WHERE pt.gender = 'F' AND pt.age >= 64 AND EXTRACT(YEAR FROM p.starttime::DATE) BETWEEN 2019 AND 2020 AND p.drug IN ('dihydropyridine', 'CCB') AND pt.subject_id IN (SELECT subject_id FROM admissions WHERE admission_type = 'IM' AND EXTRACT(YEAR FROM intime::DATE) BETWEEN 2019 AND 2020 AND gender = 'F' AND age >= 59 AND age <= 69);